procedure TFormMain.FormCreate(Sender: TObject);
begin
  // Obrigatório ANTES de ligar o SyncMode; sem isso a atribuição é ignorada.
  VVClient1.SetSysApplication(Application);
  VVClient1.SyncMode := True;

  VVClient1.SHost := '10.0.0.10'; // endereço ilustrativo
  VVClient1.SPort := 7010;
  VVClient1.AutoReconnect := True;

  if not VVClient1.Start then
    ShowMessage('Não foi possível iniciar a conexão');
end;

// iCommand e o formato dos parâmetros são definidos pelo servidor (VVProtocol).
// Cada parâmetro termina com cSep (VVHeader).
if VVClient1.SendRequest(iCommand, sParam1 + cSep + sParam2 + cSep) then
  // RP_ACK recebido
  Memo1.Lines.Add('OK: ' + VVClient1.RespData)
else
  // RP_NAK, timeout, transação em andamento ou socket desconectado
  Memo1.Lines.Add(Format('Falha: resposta=%d retcode=%d',
    [VVClient1.Response, VVClient1.RetCode]));

// Assinatura inferida das chamadas em VVClient.pas (o tipo TServerResponse fica em VVHeadType).
procedure TFormMain.VVClient1ServerResponse(Sender: TObject;
  iCommand, iResponse, iRetCode: Integer; const sData, sFiller: String);
begin
  if iResponse = RP_ACK then
    Memo1.Lines.Add(Format('Comando %d OK: %s', [iCommand, sData]))
  else
    Memo1.Lines.Add(Format('Comando %d recusado (retcode %d)', [iCommand, iRetCode]));
end;

// ctType e mtType são valores de TVVCTIConnType / TMonitorType (VVHeadType).
if VVCTIClient1.UseCTI(ctType, '10.0.0.20', 7001, 0) then
begin
  VVCTIClient1.SetDefExt('2001');
  VVCTIClient1.MonitorStart(mtType, '2001');
end;

VVCTIClient1.ACDLogon('1234', '2001');
VVCTIClient1.ACDAvail('1234');

VVCTIClient1.CallMake('2001', '01133015432');
// ... o CallID chega em OnLineEvent ...
VVCTIClient1.CallHold('2001', sCallID);
VVCTIClient1.CallRetrieve('2001', sCallID);
VVCTIClient1.CallDisconnect('2001', sCallID);

VVCTIClient1.ACDUnavail('1234', '1');
VVCTIClient1.ACDLogoff('1234');

VVRoutingClient1.SetSysApplication(Application);
VVRoutingClient1.SHost := '10.0.0.10';
VVRoutingClient1.AppType := appSMA;
VVRoutingClient1.RegID := 'APP-01';   // sem RegID o registro não é enviado
VVRoutingClient1.AutoRegister := True; // registra ao conectar e repete a cada 5 s após NAK
VVRoutingClient1.Start;

procedure TFormMain.VVRoutingClient1Registered(Sender: TObject);
begin
  // Só a partir daqui os demais métodos são aceitos (IsRegistered = True).
  VVRoutingClient1.AgentLogon('2001', '1234');
  VVRoutingClient1.AgentAvail('2001');
end;

procedure TFormMain.VVRoutingClient1AgentReserved(Sender: TObject;
  const sExtNum, sAgtID: String);
begin
  Memo1.Lines.Add('Agente ' + sAgtID + ' reservado no ramal ' + sExtNum);
end;

VVSIPClient1.SetSysApplication(Application);
VVSIPClient1.SyncMode := True;
VVSIPClient1.ChnNumber := 1;
VVSIPClient1.TransportIP := '10.0.0.30';
VVSIPClient1.UserAgent := '2001';
VVSIPClient1.Domain := 'pbx.example.com';
VVSIPClient1.UserPsw := sSenha;

if VVSIPClient1.Start and VVSIPClient1.OpenChannel then
  if VVSIPClient1.WaitRing(30000) and (VVSIPClient1.CallID <> '') then
  begin
    Memo1.Lines.Add('Chamada de ' + VVSIPClient1.ANI + ' para ' + VVSIPClient1.DNIS);
    VVSIPClient1.PlayFiles('saudacao.wav');
  end;

var
  sDigits: String;
begin
  VVSIPClient1.ClearDigits;
  // até 4 dígitos, esperando no máximo 5 s por dígito
  VVSIPClient1.GetDigits(4, 5000, sDigits);

  if sDigits = '9' then
    VVSIPClient1.BlindTransfer('2050')
  else
    VVSIPClient1.ClearCall;
end;
